package com.trevasq.qguard.service; import com.trevasq.qguard.domain.Booking; import java.time.format.DateTimeFormatter; import org.springframework.stereotype.Service;
@Service public class CalendarService { private static final DateTimeFormatter F=DateTimeFormatter.ofPattern("yyyyMMdd'T'HHmmss'Z'").withZone(java.time.ZoneOffset.UTC); public String invitation(Booking b){return "BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//TrevasQ//QGuard//EN\r\nBEGIN:VEVENT\r\nUID:"+b.getId()+"@qguard\r\nDTSTAMP:"+F.format(java.time.Instant.now())+"\r\nDTSTART:"+F.format(b.getStartsAt())+"\r\nDTEND:"+F.format(b.getEndsAt())+"\r\nSUMMARY:QGuard Demo\r\nDESCRIPTION:Your QGuard quantum cybersecurity demo.\r\nEND:VEVENT\r\nEND:VCALENDAR\r\n";} }
